package com.garyzhangscm.cwms.inventory.service;
import java.util.*;import java.lang.reflect.*;import jakarta.persistence.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;import net.bytebuddy.ByteBuddy;import net.bytebuddy.implementation.InvocationHandlerAdapter;import static net.bytebuddy.matcher.ElementMatchers.*;import com.garyzhangscm.cwms.inventory.model.*;import com.garyzhangscm.cwms.inventory.clients.*;
public class InventoryBatchChecks {
 static JdbcTemplate db;static int moved;static boolean fail;static Map<Long,Inventory> stock=new HashMap<>();static Location source,destination;static ClientRestriction restriction=new ClientRestriction(false,true,true,"");
 static void set(Object o,String name,Object v)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,v);}
 static Location location(long id,String name,boolean stage){Location l=new Location();l.setId(id);l.setName(name);Warehouse w=new Warehouse();w.setId(1L);l.setWarehouse(w);LocationGroup g=new LocationGroup();LocationGroupType t=new LocationGroupType();t.setVirtual(!stage);t.setShippingStage(stage);g.setLocationGroupType(t);l.setLocationGroup(g);return l;}
 static Inventory current(long id){Map r=db.queryForMap("SELECT * FROM inventory WHERE inventory_id=?",id);Inventory i=new Inventory();i.setId(id);i.setWarehouseId(1L);i.setLpn("TEST"+id);i.setQuantity(((Number)r.get("quantity")).longValue());i.setPickId(((Number)r.get("pick_id")).longValue());i.setItemId(3L);i.setLocationId(((Number)r.get("location_id")).longValue());stock.put(id,i);return i;}
 static List<Map<String,Object>> rows(){List<Map<String,Object>> a=new ArrayList<>();for(long id:new long[]{1,2}){Map<String,Object> r=new LinkedHashMap<>();r.put("id",id);r.put("lpn","TEST"+id);r.put("quantity",10L);r.put("pickId",id);r.put("itemId",3L);r.put("locationId",10L);r.put("warehouseId",1L);r.put("clientId",null);r.put("location",Map.of("id",10L,"locationGroup",Map.of("locationGroupType",Map.of("shippingStage",true))));a.add(r);}return a;}
 static Map<String,Object> request(){return new HashMap<>(Map.of("destinationId",20L,"rows",rows()));}
 static void reset(){db.update("DELETE FROM shipment_inventory_batch");db.update("UPDATE inventory SET location_id=10,quantity=10");moved=0;fail=false;}
 public static void main(String[] args)throws Exception{
  DriverManagerDataSource ds=new DriverManagerDataSource("jdbc:h2:mem:batch;MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);
  db.execute("CREATE TABLE shipment_inventory_batch(warehouse_id BIGINT,shipment_id BIGINT,destination_id BIGINT,request_hash VARCHAR(64),snapshot_json CLOB,completed_at TIMESTAMP,PRIMARY KEY(warehouse_id,shipment_id))");
  db.execute("CREATE TABLE shipment(shipment_id BIGINT,warehouse_id BIGINT)");db.update("INSERT INTO shipment VALUES(7,1)");
  db.execute("CREATE TABLE outbound_order(outbound_order_id BIGINT,number VARCHAR(30))");db.update("INSERT INTO outbound_order VALUES(9,'TESTORDER')");db.execute("CREATE TABLE outbound_order_line(outbound_order_line_id BIGINT,outbound_order_id BIGINT)");db.update("INSERT INTO outbound_order_line VALUES(8,9)");
  db.execute("CREATE TABLE shipment_line(shipment_line_id BIGINT,shipment_id BIGINT,outbound_order_line_id BIGINT)");db.update("INSERT INTO shipment_line VALUES(6,7,8)");
  db.execute("CREATE TABLE pick(pick_id BIGINT,shipment_line_id BIGINT,quantity BIGINT,picked_quantity BIGINT)");db.update("INSERT INTO pick VALUES(1,6,10,10),(2,6,10,10)");
  db.execute("CREATE TABLE inventory(inventory_id BIGINT,quantity BIGINT,pick_id BIGINT,location_id BIGINT,warehouse_id BIGINT,item_id BIGINT,lpn VARCHAR(20),client_id BIGINT)");db.update("INSERT INTO inventory VALUES(1,10,1,10,1,3,'TEST1',NULL),(2,10,2,10,1,3,'TEST2',NULL)");
  // H2 equivalent of UTC_TIMESTAMP(3) for the production SQL.
  db.execute("CREATE ALIAS IF NOT EXISTS UTC_TIMESTAMP FOR 'com.garyzhangscm.cwms.inventory.service.InventoryBatchChecks.utc'");
  db.execute("CREATE TABLE location(location_id BIGINT,location_group_id BIGINT)");db.update("INSERT INTO location VALUES(10,1),(20,2)");db.execute("CREATE TABLE location_group(location_group_id BIGINT,location_group_type_id BIGINT)");db.update("INSERT INTO location_group VALUES(1,1),(2,2)");db.execute("CREATE TABLE location_group_type(location_group_type_id BIGINT,shipping_stage_locations BOOLEAN)");db.update("INSERT INTO location_group_type VALUES(1,TRUE),(2,FALSE)");
  ShipmentInventoryBatchService s=new ShipmentInventoryBatchService();set(s,"db",db);set(s,"transactionManager",new DataSourceTransactionManager(ds));source=location(10,"STAGE",true);destination=location(20,"TESTORDER",false);
  WarehouseLayoutServiceRestemplateClient layout=new ByteBuddy().subclass(WarehouseLayoutServiceRestemplateClient.class).method(named("getLocationById")).intercept(InvocationHandlerAdapter.of((o,m,a)->((Long)a[0])==10?source:destination)).make().load(InventoryBatchChecks.class.getClassLoader()).getLoaded().getDeclaredConstructor().newInstance();set(s,"layout",layout);
  EntityManager em=(EntityManager)Proxy.newProxyInstance(InventoryBatchChecks.class.getClassLoader(),new Class[]{EntityManager.class},(o,m,a)->{if(m.getName().equals("find"))return current((Long)a[1]);return null;});set(s,"em",em);
  InventoryService inv=new ByteBuddy().subclass(InventoryService.class).method(named("shipInventory")).intercept(InvocationHandlerAdapter.of((o,m,a)->{long id=(Long)a[0];db.update("UPDATE inventory SET location_id=20 WHERE inventory_id=?",id);moved++;if(fail&&moved==2)throw new IllegalStateException("Injected failure");Inventory i=stock.get(id);i.setLocationId(20L);return i;})).make().load(InventoryBatchChecks.class.getClassLoader()).getLoaded().getDeclaredConstructor().newInstance();set(s,"inventory",inv);
  TransactionTemplate tx=new TransactionTemplate(new DataSourceTransactionManager(ds));
  reset();s.ship(1,7,request(),restriction);if(moved!=2||db.queryForObject("SELECT COUNT(*) FROM shipment_inventory_batch WHERE completed_at IS NOT NULL",Integer.class)!=1)throw new AssertionError("commit");
  s.ship(1,7,request(),restriction);if(moved!=2)throw new AssertionError("duplicate move");
  try{Map r=request();((List<Map>)r.get("rows")).get(0).put("quantity",11L);s.ship(1,7,r,restriction);throw new AssertionError("changed replay accepted");}catch(RuntimeException expected){}
  reset();fail=true;try{s.ship(1,7,request(),restriction);throw new AssertionError();}catch(RuntimeException expected){}if(db.queryForObject("SELECT COUNT(*) FROM inventory WHERE location_id=20",Integer.class)!=1||db.queryForObject("SELECT COUNT(*) FROM shipment_inventory_batch WHERE completed_at IS NULL",Integer.class)!=1)throw new AssertionError("partial receipt");
  fail=false;moved=0;s.ship(1,7,request(),restriction);if(moved!=1||db.queryForObject("SELECT COUNT(*) FROM inventory WHERE location_id=20",Integer.class)!=2)throw new AssertionError("resume repeated committed pallet");
  reset();db.update("UPDATE inventory SET quantity=9 WHERE inventory_id=2");try{s.ship(1,7,request(),restriction);throw new AssertionError();}catch(RuntimeException expected){}if(moved!=0)throw new AssertionError("validated after movement");
  reset();Map r=request();((List)r.get("rows")).remove(0);try{s.ship(1,7,r,restriction);throw new AssertionError();}catch(RuntimeException expected){}if(moved!=0)throw new AssertionError("subset accepted");
  reset();java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);java.util.concurrent.CountDownLatch go=new java.util.concurrent.CountDownLatch(1);List<java.util.concurrent.Future<?>> futures=new ArrayList<>();for(int t=0;t<2;t++)futures.add(pool.submit(()->{try{go.await();s.ship(1,7,request(),restriction);}catch(Exception e){throw new RuntimeException(e);}}));go.countDown();for(java.util.concurrent.Future<?> f:futures)f.get();pool.shutdown();if(moved!=2)throw new AssertionError("Concurrent submission duplicated stock move");
  System.out.println("PASS concurrent same-batch submissions move each inventory once");
  System.out.println("PASS batch commit, idempotent replay, changed replay rejection, partial failure/resume without repeating first pallet, changed quantity before any move, incomplete inventory set rejection");
 }
 public static java.sql.Timestamp utc(int precision){return new java.sql.Timestamp(System.currentTimeMillis());}
}
